import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"大過","description":"高岛易断 - 大過","frontmatter":{"title":"大過","description":"高岛易断 - 大過"},"headers":[],"relativePath":"zh/classics/takashima/028.md","filePath":"zh/classics/takashima/028.md"}'),i={name:"zh/classics/takashima/028.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h2 id="大過-1" tabindex="-1">大過 <a class="header-anchor" href="#大過-1" aria-label="Permalink to “大過”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>大过：栋挠，利有攸往，亨。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《大过》，阳大阴小，刚积于中，足以任重，有似栋然；《兑》上《巽》下，《巽》为木，《兑》为毁折，木而毁折，栋斯挠矣。当此大厦将倾，非一木所能支，惟当出门求助，以拯患难，乃得亨通，故曰“利有攸往，亨”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽灭木，大过。君子以独立不懼，遁世无闷。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>此卦泽水浸淫《巽》木之上，木为之枯，故曰“泽灭木”。当是时，世俗之士，或皆随流逐波，鲜有不磨灭者矣，惟君子具《大过》人之才干，虽时当困厄，而操守弥坚，所信者理，所乐者天，谓之“独立不惧，遁世无闷”。是必刚而能柔，过而能往，可谓善处《大过》之时者也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：“灭”，灭绝也，大欲灭国，小欲灭身，其象凶矣。行军占此，恐有暴水淹没之祸。</p><p>○　问营商：《象》曰“泽灭木”，有低价忽而高涨之势。</p><p>○　问功名：“独立不懼，遁世无闷”者，谓当退身隐处，未可求名也。</p><p>○　问家宅：《兑》泽在上，《巽》木在下，其象反复，位置不正，防有灭凶之祸。</p><p>○　问疾病：是肝火内郁之症，肾气冲上，医治非易。</p><p>○　问婚嫁：“泽灭木”，恐配偶之间，有老幼不匀。</p><p>○　问六甲：生女。</p><p>○　问失物：必坠入水沟之处。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“藉”者，铺地也，“白茅”，取其洁也，古者祭祀，藉之灌酒，以降神也。茅白取《巽》象，《巽》在下卦，藉茅于下，所以承上之刚也。初爻阴柔居下，不犯刚而能承刚，当此《大过》之时，敬慎事上，不得谓过分也。故比之礼义之适中者，则有过于敬慎之失，比之傲慢侮人者，则其胜亦不啻霄壤；在高傲者固有咎，而卑下者必无咎焉。盖茅柔物也，藉之足以相助，未可以茅之微而忽之。《象》曰“柔在下也”，以爻言则初在下，以茅言则藉在下。初六居阴，阴为柔，茅质柔弱，故曰“柔在下也”。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问战征：当此初次出师，最忌刚暴过甚，宜宽柔待下。</p><p>○　问营商：贩运之货，必是药品，或是茶叶木棉，其色必白，其质必柔，均可获利。</p><p>○　问功名：拔茅连茹，是有连类同登之象。</p><p>○　问家宅：其宅必近卑湿低下之处，屋外蔓草荒芜，建筑也。</p><p>○　问疾病：病体柔弱，下焦有湿，须用温燥之药治之。</p><p>○　问失物：于草地上觅之。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治元年，东久世中将、锅岛肥前守充先锋，将收横滨，余时在肥前守营中，兼管各种事务。藩士下村某，率兵士百人，奉命先收浦贺，以向导嘱余，为筮一卦。筮得《大过》之《夬》。</p><p>断曰：凡古军事，内卦为我，外卦为敌。初爻在内卦之下，以阴居阳，阴属柔，显见我宜用柔。兑为泽，所攻取者，必是水泽之地。白茅柔软之物，用以藉地，履之而安，无失足之虞，是教我喜啣尾潜进也。今闻浦贺港上，有开阳、回天以下六舰碇泊，募兵脱走者数干人搭载之，浦贺兵士，又与之同心联络，敌势过盛，未便用强攻击。爻辞曰“藉用白茅”，《象》曰“柔在下也，”是明示以用柔之道，以柔克刚，收取海门咽喉为上策也。下村某，率领十数人前进，不战而平。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>二爻以阳居阴，阴尽则死，阳来则生，物之常理。《巽》为木，克为泽，木之近水者为杨，泽而灭木，杨必枯矣，得九二阳气生助，故得枯而《复》生。“稊”，杨之秀也。按，二爻体《乾》，《乾》为老，为男，故曰“老夫”；下得《巽》在初，《巽》为处女，故曰“女妻”；二与初比而得初，故曰“老夫得其女妻”。夫夫妇配偶，以年之相若为正，老夫女妻，是亦颠也，然老少虽非正匹，而阴阳自得相济。“老夫”“女妻”，犹枯杨之生稊，终得妊育也，故曰“无不利”。《象》曰“过以相与也”，卦之义在刚过，夫而过老，妻而过少，故曰“过以相与”。《杂卦传》曰，“大过颠也”，斯之谓欤？</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问战征：有转败为胜之象。</p><p>○　问营商：《兑》为阴，亦为金，《巽》为风，亦为木，定为金木生意。“枯杨生稊”，于种植林木，或贩运树木，皆“无不利”。</p><p>○　问功名：就爻象看来，必待晚年，方可成名。</p><p>○　问家宅：此宅昔年定多不利，系阳宅居于阴地；近来得阳九发动，必有枯树开花，此其兆也。利。</p><p>○　问婚姻：主有老鳏重娶，得以生育，大利。</p><p>○　问疾病：虽危得安。</p><p>○　问失物：必得。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>明治二十二年，友人来请占某家气运，筮得《大过》之《咸》。</p><p>断曰：此卦上《兑》下《巽》，是以《兑》少女，居《巽》长女之上，少女不善理家，长女将取而代之，故一家因此有颠覆之患。今占某家得此爻，家业之衰，得人理之，自然复盛，犹木之既枯，得阳气发动，自然生稊。人虽既老，得配少妻，亦能生育，皆有既败复成之象，所谓“枯杨生稀，老夫得其女妻，无不利”者是也。</p><p>明治二十七年十二月，我军入海城，有敌将宋庆乘雪中通路，屡来逆袭挑战，海城几危。筮得《大过》之《咸》。</p><p>断曰：此卦合上下二卦，有坎险之象，是两军共履困难。今爻辞曰“枯杨生稊”，杨以冬枯春生，必待春暖，我军乃可突击。“老夫得其女妻，无不利”，是我《师》既老，必得新来之兵，发助壮气，可以制胜也。后果有第二军精兵新来，占领盖平，声援海城。二月十四日克太平山，三月四日占领牛庄，六日占领营口，九日陷田庄台。</p><p>明治三十一年，占我国与清国交际，筮得《大过》之《咸》。</p><p>断曰：此卦《兑》上《巽》下，《兑》为金，为泽，属正西；《巽》为风，为木，属东南；金来克木，显见西来侵夺东南，《象》曰“泽灭木”，是其兆也。今占得二爻，二爻以阳处阴，爻辞谓“枯杨生稊”，杨即《巽》木，为泽所灭，故“枯”。“枯”者衰败之象，足见东南之衰弱；“生稀”者是得春阳之发动也；“老夫”者，亦衰象，“得其女妻”，是得少阴之相助也。论我日本与清国，皆地居东南，朝鲜一国，介在我两国之间，我国向欲与清国合力保护朝鲜，清国以朝鲜为属邦，不容我议，我两国因之启战，清国败北。割地讲和后，俄、德、法三国联合，意属护清，逼我割还辽东；在三国包藏祸心，未必不借此为功，迫索清国，分割要地，此亦势所必至也。清国近知欧洲列国之不可恃，愿联盟，我国亦愿从此与清国合保东南，力拒欧西，犹如“枯杨”之“生稊”。《象》曰“过以相与也”，以言我两国昔日相战，今日相和，是“过以相与”也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>就全卦言，四刚连亘在中，如屋有栋，上下两阴皆弱，故“挠”。就三爻言，九三互《乾》，辰在亥，上值危宿，按危三星，在虚东北，形如盖屋，有栋之象。三以刚居刚，过而又过，过刚必折，故“挠”。九三刚愎自用，视群策群力，皆莫己若，遂至孤立无助，愈高愈危，终致“栋挠”之凶。《象》曰“不可以有辅也”，言三予智自雄，不能与人共事，集思广益，故不可相辅有成也。亦三自取之耳。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：“栋”者一屋之主，即一军之主帅也；“挠”者，摧折也，栋而挠，是主帅受伤之象。弊在主帅过于刚猛，不听人言所致，故凶。</p><p>○　问营商：商业必须得人为辅，方能成事，若自运自刃，非特经营不大，且恐致意外耗失。“栋挠”云者，有人财两失之虑，故凶。</p><p>○　问功名：能任大任者，称栋梁之材，云“挠”，则栋非其栋矣，虽成终败，凶。</p><p>○　问家宅：此宅不吉，栋折榱崩，不可居也，凶。</p><p>○　问婚嫁：九三以阳居阳，孤阳无助，婚姻不成，成亦不吉。</p><p>○　问六甲：生男，恐不能养。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十三年某月，友人某来曰：依市町村制，将选举市长。我市民向所瞩望者，有甲乙二人，我以甲为适当，故将投票，请占其成败。筮得《大过》之《困》。</p><p>断曰：此卦四阳居中为栋，初上二阴柔弱，不克任重，故“挠”。今占选举市长得此爻，在甲方才力俱强，足以任事，但恃己傲人，刚愎过甚，刚则必折，挠之所由来也。三爻以阳居阳，是谓过而又过，虽与上六相应，上爻以阴居阴，柔弱无力，纵极力为之推荐，无能为也。四爻为乙，曰“栋隆”，得选必在四矣，甲无望焉。后果如此占。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>九三曰“栋挠”，九四曰“栋隆”，其义相反，以九四在下卦之上，以阳居阴，亦过而不过也。下与初应，初爻虽弱，得其所藉，即可不挠。按九四辰在午，上值张，南宫候曰，“张为天府”，故有栋象。“隆”，《说文》曰，“丰大也”；《玉篇》曰，“中央高也”。栋以任重，故宜大栋在屋中，故宜高。高必以下为基，下有所藉，斯高而不危。三之所以挠者，下无藉也；四得其藉，故隆。凡事之得所凭藉，而大险可济，大功可成，上不辜君之托，下不负民之望，皆犹是也，其吉可知，故曰“栋隆，吉”。“有它，吝”者，言四若怀他志，厌初之本弱，而不屑用其藉，则三之挠，即为四之挠，必不免于吝矣。《象》曰“不桡乎下也”，谓栋既隆起，下必不挠也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：行军屯营，宜占高阜要地，下有所藉，斯营基巩固，可进可退，自不为敌所挠也，故吉。</p><p>○　问营商：想必是材木生意，木料高大，足备巨室之用，若他项经营，恐未必隹。</p><p>○　问功名：爻曰“栋隆”，必是大才，可当大任，斯足副“栋隆”之兆，其他小试，非其所长，有不屑为也。</p><p>○　问家宅：此宅栋榱辉煌，门户宏阔，吉。</p><p>○　问疾病：想是中胸有痞块高起，然无害。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>有甲乙两会社，同业相竞，一日甲社社长某来曰：今当市内贩路之点，势难两立，因请一占。筮得《大过》之《井》。</p><p>断曰：卦名《大过》，是刚过也，而当地立两社，亦为过分。占得四爻，爻曰“栋隆，吉”，此卦三四两爻，皆取象于栋，犹之二社并立也。可知甲乙之争，即在此三四两爻：乙社九三，以阳居阳，是材力与资本俱足，其应为上爻，上爻无可凭藉；甲社为九四，以阳居阴，材力与资本稍卑，其应为初爻，初爻得其所藉。有藉者“隆”，无藉者“挠”，甲社胜矣，谓之“栋隆，吉”。后果甲兴乙仆。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“枯杨”之解，见九二下。此爻与上六阴阳相比，得阴之助而生华，故曰“枯杨生华”。杨华无实，飘荡随尽，荣无几时也。九二以得初阴之助而“生稊”，九五下无有助，惟与上六相比，犹断根之杨，得雨露之润，虽一旦发华，不久凋落。“老妇”指上六，喻上六阴极而衰；“士夫”指九五，喻九五之无内助。“士”，未娶妻者之称，即谓少年。阴而居上，故呼“老妇”；阳而居下，故称“士夫”，是亦《大过》之义也。九五以刚在刚，三阳皆不为用，独与上六阴阳相比，故曰夫妇。从夫妇之序而论，当曰士夫得老妇，今曰老妇得士夫者，原其配偶之所起，志出老妇，老妇首倡而求士夫，丑体尤在老妇，亦以见圣人尽人情、考世故之妙也。《象传》曰“老夫士夫，亦可丑也”，丑者污辱之义，深恶之之辞也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问战征：行军占此，必军中主将偏裨，位置颠倒，任用不当。一时虽获胜仗，未能持久。</p><p>○　问营商：防经商者贪恋外遇，致播丑声。</p><p>○　问家宅：防闺房不正，墙侧有茨。</p><p>○　问功名：必主晚年获隽。</p><p>○　问婚嫁：必年齿不齐，匹偶不正。</p><p>○　问六甲：生女，不育。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治十七年，因朝鲜滋事，占日清关系。</p><p>断曰：此番朝鲜发炮启衅，不特关涉朝鲜，即关涉清国，是三国中一大关涉之事也。在朝鲜，孱弱已极，譬如枯杨，即一时开花，不久遂零落矣。清国且以朝鲜为属邦，朝鲜政令，悉皆听命于清，俨如少男受制于老妇也。今我国受朝鲜之辱，必将大启兵端。清国亦知其然，故愿与议和。就爻象而细究之，知日清必不至决裂也，其间机密，爻象虽露，未可显言焉。</p><p>明治十八年夏，余避暑于箱根，与贵显某某等同宿旅舍中。一日相与闲游山野，某贵显曰：此间幽闲僻静，觅一胜地，结一别墅，足以避嚣，足以娱老，洵可乐也！足下亦有意否？闻言亦觉欣然，既而思之，不能自决，为占一卦，筮得《大过》之《恒》。</p><p>断曰：五爻以阳居阳，贵显属阳，未可以闲退也。就其地论，箱根属在东海道，是为《巽》木之位，爻曰“枯杨生华”，知箱根繁盛，亦不久矣；且游客往来，多在避暑之时，过此鲜有到者。“老妇得其士夫”者，以喻箱根之地，名胜久著，若老妇之素有艳名。“士夫”者，少年也，少年闻其名，未涉其胜，是以多来游赏。究之一过即往，“无咎”亦“无誉”也。且少年人不识风雅，反来作践，故《象》曰“亦可丑也”。因谢某贵显之劝。</p><p>明治三十一年，占国民协会气运，筮得《大过》之《恒》。</p><p>断曰：五爻以阳居阳，是过而又过，宜其民心盛强，而爻辞曰“枯杨”何也？盖以《巽》本柔木，一经《兑》泽所灭，几成枯木，虽一时复华，亦不久摇落矣。且阳至五而极，阳极则衰，阳将变而为阴，故称“老妇”。“士夫”，少男也，近年社会，往往多用少年，亦时势使然也，故曰“老妇得其士夫”。究之老大者无能，反以少年之议论为得计，噫！“亦可丑也”。爻曰“无咎无誉”，可知本年协会之气运，”亦无荣无辱而已。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“过涉灭顶”者，谓犯危险而涉河，不得达岸，水没其首也。互卦《乾》为首，爻例上为顶，上六《兑》爻，《兑》为水泽，位在酉，上值胃，附星积水，石氏云“积水星明，则大水出”，故有“过涉灭顶”之象。六爻以阴居阴，才力俱弱，但其志在救时，虽履患踏险，明知“过涉”之多凶，而忘身济国，有不遑反顾者，即使其功不成，其志深足尚焉，复有何咎？此所谓勇士不忘在沟壑，志士不忘丧其元，万世纲常，正赖此辈以存也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问战征：恐有主将阵亡之惨。</p><p>○　问功名：有头悬梁、锥刺之苦志，宜其声名远达，有志竟成。</p><p>○　问营商：运货出洋，最宜谨慎。</p><p>○　问疾病：恐水气上冲，头面浮肿，凶。</p><p>○　问家宅：恐有大水泛涨，墙倾屋倒之患。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>某县人携友人某之书来曰：今谋新创一事业，深有所虑，请占其成否如何？筮得《大过》之《姤》。</p><p>断曰：六爻居《兑》卦之终，志在救时，未免过于决裂，是以凶也。今足下占事而得此爻，知足下所谋事业，有关公益，但其中事多颠覆，率意径行，祸有不测，还宜待时而动，毋蹈于危，徒自苦耳。切嘱切嘱！后此人不用此占，遂至失败。</p><p>明治二十八年，占我国与法国交际，筮得《大过》之《姤》。</p><p>断曰：上爻居外卦之极，殆谓外交既平以后，又将别起一波乎？爻辞曰“过涉灭顶，凶”，我国自过海远征，清国战败，我军即此凯旋。就爻象《观》之，或者他国谓我刚强过甚，将有出而干涉其事者，亦未可知也。后果有俄、法、德三国同盟，干涉与清国和款，逼我即还辽东。我政府措置，能适此卦意，无事结局云。</p>',102)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
